1	import { Alert, App, Button, Card, Flex, Form, Input, Typography } from 'antd';
2	import { useEffect, useState } from 'react';
3	import { useNavigate, useParams } from 'react-router-dom';
4	
5	import { getConnection, listConnections } from '../api/connections';
6	import { createCheck, getSuite } from '../api/suites';
7	import { buildCheckPayload, buildComparisonPayload } from '../components/checks/checkForm';
8	import { ComparisonCheckForm } from '../components/checks/ComparisonCheckForm';
9	import {
10	  ConfigFieldItem,
11	  DimensionField,
12	  SeverityThresholdFields,
13	} from '../components/checks/checkFormFields';
14	import { ColumnProfilePanel } from '../components/checks/ColumnProfilePanel';
15	import { DryRunPreview } from '../components/checks/DryRunPreview';
16	import {
17	  configFieldsFor,
18	  EXPECTATION_BY_TYPE,
19	  expectationsByCategoryFor,
20	  fieldVisible,
21	  type ExpectationCategory,
22	} from '../components/checks/expectationCatalog';
23	import { Page } from '../components/layout/Page';
24	import { useAsyncAction } from '../hooks/useAsyncAction';
25	import { apiFieldError } from '../utils/fieldErrors';
26	import { useAsyncData } from '../hooks/useAsyncData';
27	
28	/**
29	 * Dedicated full-page check authoring flow (GX-Cloud style): pick a category → pick an expectation
30	 * → fill its config + thresholds.
31	 */
32	export function CheckNew() {
33	  const navigate = useNavigate();
34	  const { suiteId } = useParams<{ suiteId: string }>();
35	  const { message } = App.useApp();
36	  const [category, setCategory] = useState<ExpectationCategory>();
37	  const [expectationType, setExpectationType] = useState<string>();
38	  const [form] = Form.useForm();
39	  const column = Form.useWatch(['config', 'column'], form) as string | undefined;
40	  // Drives which conditional fields render (anomaly's `column`, #593 — ConfigField.showWhen) — the
41	  // whole `config` object, not just one key.
42	  const configValues = Form.useWatch('config', form) as Record<string, unknown> | undefined;
43	  const { run, loading: submitting } = useAsyncAction('Create failed');
44	  // Load the suite + its connection together: the run target (#215) drives the dry-run preview's
45	  // table/schema, and the connection type gates the Custom-SQL category (ADR 0019 — SQL
46	  // datasources only).
47	  const { state } = useAsyncData(async () => {
48	    if (!suiteId) throw new Error('no suite');
49	    const suite = await getSuite(suiteId);
50	    // Best-effort: a suite may be readable while its connection isn't (shared suite).
51	    const connection = await getConnection(suite.connection_id).catch(() => null);
52	    // The comparison editor's source picker; best-effort like the connection.
53	    const connections = await listConnections().catch(() => []);
54	    return { suite, connection, connections };
55	  });
56	  const target = state.status === 'ok' ? state.data.suite.target : null;
57	  const connectionType = state.status === 'ok' ? state.data.connection?.type : undefined;
58	  const categories = expectationsByCategoryFor(connectionType);
59	
60	  const backToSuite = () => navigate(suiteId ? `/suites/${suiteId}` : '/suites');
61	  const spec = expectationType ? EXPECTATION_BY_TYPE[expectationType] : undefined;
62	
63	  // Start the config form clean each time an expectation is (re)picked — after the <Form> mounts
64	  // (it only renders in the config step).
65	  useEffect(() => {
66	    if (expectationType) form.resetFields();
67	  }, [expectationType, form]);
68	
69	  // A save refusal that has no form field to land on (see below). Kept in state
70	  // rather than shown as a toast so it stays on screen while the author reacts.
71	  const [refusal, setRefusal] = useState<string | null>(null);
72	
73	  const onFinish = (values: Record<string, unknown>) => {
74	    setRefusal(null);
75	    if (!suiteId || !expectationType) return;
76	    const isComparison = EXPECTATION_BY_TYPE[expectationType]?.kind === 'comparison';
77	    return run(async () => {
78	      try {
79	        await createCheck(
80	          suiteId,
81	          isComparison
82	            ? buildComparisonPayload({ ...values, expectation_type: expectationType })
83	            : buildCheckPayload({ ...values, expectation_type: expectationType }),
84	        );
85	      } catch (err) {
86	        // A refusal about the *chosen expectation* (the sampling to row-count conflict, #1333 F5)
87	        // has no form field to land on here — the type was picked in the previous step.
88	        const api = apiFieldError(err);
89	        if (api && typeof api.detail.field === 'string') {
90	          setRefusal(api.message);
91	          return;
92	        }
93	        throw err;
94	      }
95	      message.success(`${values.name as string}: created`);
96	      backToSuite();
97	    });
98	  };
99	
100	  // Step 3 — config + thresholds for the chosen expectation.
101	  if (spec) {
102	    return (
103	      <Page width={'form'}>
104	        <Header
105	          title={spec.label}
106	          onBack={() => setExpectationType(undefined)}
107	          backLabel="Back to expectations"
108	        />
109	        <Form form={form} layout="vertical" onFinish={onFinish}>
110	          <Typography.Paragraph type="secondary" style={{ marginTop: -8 }}>
111	            {spec.description}
112	          </Typography.Paragraph>
113	          {refusal && (
114	            <Alert
115	              type="error"
116	              showIcon
117	              style={{ marginBottom: 16 }}
118	              data-testid="check-refusal"
119	              title="This check can’t be added to the suite"
120	              description={refusal}
121	            />
122	          )}
123	          <Form.Item name="name" label="Name" rules={[{ required: true }]}>
124	            <Input placeholder="e.g. order_id not null" />
125	          </Form.Item>
126	          {spec.kind === 'comparison' ? (
127	            <ComparisonCheckForm
128	              connections={state.status === 'ok' ? state.data.connections : []}
129	              suiteConnectionName={state.status === 'ok' ? state.data.connection?.name : undefined}
130	              suiteConnectionType={connectionType}
131	              targetSummary={targetSummary(target)}
132	            />
133	          ) : (
134	            configFieldsFor(spec, connectionType)
135	              .filter((field) => fieldVisible(field, configValues))
136	              .map((field) => (
