30	/** Dedicated full-page edit-check flow (ADR 0022 — replaces the edit drawer). */
31	export function CheckEdit() {
32	  const { suiteId, checkId } = useParams<{ suiteId: string; checkId: string }>();
33	  return <CheckEditView key={checkId} suiteId={suiteId} checkId={checkId} />;
34	}
