36	function CheckEditView({ suiteId, checkId }: { suiteId?: string; checkId?: string }) {
37	  const navigate = useNavigate();
38	  const back = () => navigate(suiteId ? `/suites/${suiteId}` : '/suites');
39	  // Load the suite (target + datasource type) and the check together: the target drives the dry-run
40	  // preview, the connection type gates Custom SQL (ADR 0019), and the check seeds the form.
41	  const { state, reload } = useAsyncData(async () => {
42	    if (!suiteId || !checkId) throw new Error('no check');
43	    const suiteP = getSuite(suiteId);
44	    // Best-effort: a suite may be readable while its connection isn't (shared
45	    // suite). The connection only gates the Custom-SQL category.
46	    const connectionP = suiteP.then((s) => getConnection(s.connection_id)).catch(() => null);
47	    const [suite, check, connection] = await Promise.all([
48	      suiteP,
49	      getCheck(suiteId, checkId),
50	      connectionP,
51	    ]);
52	    return { suite, check, connection };
53	  });
54	
55	  return (
56	    <Page width={'form'}>
57	      <Flex justify="space-between" align="center" gap={12} wrap>
58	        <Typography.Title level={3} style={{ margin: 0 }}>
59	          {state.status === 'ok' ? `Edit “${state.data.check.name}”` : 'Edit check'}
60	        </Typography.Title>
61	        <Button onClick={back}>Cancel</Button>
62	      </Flex>
63	
64	      {state.status === 'loading' && <Spin description="Loading check…" />}
65	      {state.status === 'error' && (
66	        <PageError
67	          error={state.error}
68	          kind={state.kind}
69	          httpStatus={state.httpStatus}
70	          requestId={state.requestId}
71	        />
72	      )}
73	      {state.status === 'ok' && suiteId && (
74	        <Card size="small">
75	          <CheckEditForm
76	            suiteId={suiteId}
77	            check={state.data.check}
78	            target={state.data.suite.target}
79	            connectionType={state.data.connection?.type}
80	            // History's Restore action is edit-gated the same way the rest of
81	            // the suite's write actions are (Suites.tsx `canRun`).
82	            canRestore={canRunSuite(state.data.suite)}
83	            onRestored={reload}
84	            onCancel={back}
85	            onSaved={back}
86	          />
87	        </Card>
88	      )}
89	    </Page>
90	  );
91	}
