93	function CheckEditForm({
94	  suiteId,
95	  check,
96	  target,
97	  connectionType,
98	  canRestore,
99	  onRestored,
100	  onCancel,
101	  onSaved,
102	}: {
103	  suiteId: string;
104	  check: Check;
105	  target: Record<string, unknown> | null;
106	  connectionType?: ConnectionType;
107	  /** Whether the caller may restore a version (#283) — passed straight through
108	   *  to `CheckHistoryDrawer`. */
109	  canRestore: boolean;
110	  /** Refetches the suite/check/connection after a successful restore, so the
111	   *  form re-seeds from the restored (live) state. */
112	  onRestored: () => void;
113	  onCancel: () => void;
114	  onSaved: () => void;
115	}) {
116	  const { message } = App.useApp();
117	  const [form] = Form.useForm();
118	  const { run, loading: submitting } = useAsyncAction('Save failed');
119	  const [historyOpen, setHistoryOpen] = useState(false);
120	  const [trendOpen, setTrendOpen] = useState(false);
121	  const selectedType = Form.useWatch('expectation_type', form) as string | undefined;
122	  const column = Form.useWatch(['config', 'column'], form) as string | undefined;
123	  // Drives which conditional fields render (anomaly's `column`, #593 —
124	  // ConfigField.showWhen); see CheckNew's matching watch for the rationale.
125	  const configValues = Form.useWatch('config', form) as Record<string, unknown> | undefined;
126	  const spec = selectedType ? EXPECTATION_BY_TYPE[selectedType] : undefined;
127	  // `kind` is immutable on update (a freshness check can't become an expectation),
128	  // so a monitor check locks its type — only its config + thresholds are editable.
129	  const isMonitor = check.kind !== 'expectation';
130	  // Comparison checks (ADR 0015) edit only name + thresholds here — the source/dataset config is
131	  // authored on the dedicated side-by-side page (recreate to re-shape; repointing stays an API
132	  // affair for now).
133	  const isComparison = check.kind === 'comparison';
134	
135	  // Seed from the loaded check once.
136	  useEffect(() => {
137	    form.setFieldsValue({
138	      name: check.name,
139	      expectation_type: check.expectation_type,
140	      config: configToForm(EXPECTATION_BY_TYPE[check.expectation_type], check.config),
141	      // The STORED value, not the derived default (ADR 0038): an override must survive a re-open.
142	      dimension: check.dimension ?? undefined,
143	      warn_threshold: check.warn_threshold ?? undefined,
144	      fail_threshold: check.fail_threshold ?? undefined,
145	      critical_threshold: check.critical_threshold ?? undefined,
146	    });
147	  }, [check, form]);
148	
149	  // Changing the expectation type re-derives the dimension, mirroring the create page (which resets
150	  // the whole form on type change).
151	  const initialType = check.expectation_type;
152	  useEffect(() => {
153	    if (selectedType && selectedType !== initialType) {
154	      form.setFieldsValue({ dimension: EXPECTATION_BY_TYPE[selectedType]?.dimension });
155	    }
156	  }, [selectedType, initialType, form]);
157	
158	  const onSubmit = async () => {
159	    let values: Record<string, unknown>;
160	    try {
161	      values = await form.validateFields();
162	    } catch {
163	      return; // inline validation errors
164	    }
165	    await run(async () => {
166	      // `kind` is immutable on update — omit it from the PATCH (don't rely on the backend silently
167	      // ignoring an extra field).
168	      const update = isComparison
169	        ? {
170	            name: values.name as string,
171	            dimension: (values.dimension as string | undefined) ?? null,
172	            warn_threshold:
173	              typeof values.warn_threshold === 'number' ? values.warn_threshold : null,
174	            fail_threshold:
175	              typeof values.fail_threshold === 'number' ? values.fail_threshold : null,
176	            critical_threshold:
177	              typeof values.critical_threshold === 'number' ? values.critical_threshold : null,
178	          }
179	        : (() => {
180	            const u = buildCheckPayload(values);
181	            delete u.kind;
182	            return u;
183	          })();
184	      try {
185	        await updateCheck(suiteId, check.id, update);
186	      } catch (err) {
187	        // The backend names the field it refused on (e.g. the sampling to row-count conflict, #1333
188	        // F5).
189	        const api = apiFieldError(err);
190	        const field = api?.detail.field;
191	        if (api && typeof field === 'string') {
192	          form.setFields([{ name: field, errors: [api.message] }]);
193	          return;
194	        }
195	        throw err;
196	      }
197	      message.success(`${values.name as string}: saved`);
198	      onSaved();
199	    });
200	  };
201	
202	  return (
203	    <>
204	      <Form form={form} layout="vertical" onFinish={onSubmit}>
205	        <Form.Item name="name" label="Name" rules={[{ required: true }]}>
206	          <Input placeholder="e.g. order_id not null" />
207	        </Form.Item>
208	        <Form.Item
209	          name="expectation_type"
210	          label={isMonitor ? 'Monitor' : 'Expectation'}
211	          rules={[{ required: true }]}
212	          extra={
213	            isMonitor ? 'A monitor’s kind is fixed — recreate the check to change it.' : undefined
214	          }
215	        >
216	          <Select
217	            placeholder="Select an expectation"
218	            // A monitor's kind is immutable, so lock the type for monitor checks.
219	            disabled={isMonitor}
220	            // Grouped by category (antd optgroups).
221	            options={expectationsByCategoryFor(connectionType, check.expectation_type).map((g) => ({
222	              label: g.category,
223	              options: g.specs.map((e) => ({ value: e.type, label: e.label })),
224	            }))}
225	          />
226	        </Form.Item>
227	
228	        {spec && (
229	          <>
230	            <Typography.Paragraph type="secondary" style={{ marginTop: -8 }}>
231	              {spec.description}
232	            </Typography.Paragraph>
233	            {configFieldsFor(spec, connectionType)
234	              .filter((field) => fieldVisible(field, configValues))
235	              .map((field) => (
236	                <ConfigFieldItem
237	                  key={field.name}
238	                  field={field}
239	                  connectionType={connectionType}
240	                  configValues={configValues}
241	                />
242	              ))}
243	            <DimensionField spec={spec} />
244	          </>
245	        )}
246	
247	        <SeverityThresholdFields monitor={spec?.thresholds} />
248	
249	        {!isComparison && (
250	          <Form.Item>
