export interface ExpectationSpec {
  /** snake_case GX expectation type (or `monitor:<kind>`) sent to the backend. */
  type: string;
  /** Check kind (ADR 0012); defaults to `expectation` when omitted. */
  kind?: CheckKind;
  label: string;
  description: string;
  category: ExpectationCategory;
  /** The DQ dimension this check type measures (ADR 0038) — the editor's derived default. */
  dimension?: DqDimension;
  fields: ConfigField[];
  /** Present for monitor kinds — drives the threshold block's help/bounds/required. */
  thresholds?: MonitorThresholdSpec;
  /**
   * The engine this type runs on (ADR 0036). Omitted = `gx` (every non-Snowflake
   * connection, and most Snowflake checks too). Only the `dmf:*` types below fix
   * it to `dmf` — DMF is a distinct expectation-type-per-metric, not a toggle on
   * an existing GX type, because the backend validates `expectation_type` and
   * `engine` together (`validate_engine_compatibility`).
   */
  engine?: CheckEngine;
  /**
   * `dmf:unique_count` degrades DOWNWARD (fewer distinct values = worse), so the
   * backend REJECTS any threshold on it (`DMF_UNBANDABLE_TYPES`) rather than
   * silently misinterpreting "higher = worse" — the editor must not offer the
   * fields at all, not just leave them optional.
   */
  noThresholds?: boolean;
}

/** The one type shared by both engines — Freshness is `kind: 'freshness'` either
 *  way; only `engine` distinguishes the GX SQL/dataframe path from Snowflake's
 *  native `FRESHNESS` DMF (`snowflake_dmf.py`, ADR 0036 §6). Exported so the
 *  editor can show an engine choice on this ONE spec without a second catalog
 *  entry — `validate_monitor_check` requires `expectation_type` to be exactly
 *  this string regardless of engine, so a `monitor:freshness_dmf` twin would
 *  422. */
export const FRESHNESS_EXPECTATION_TYPE = 'monitor:freshness';

/** Snowflake connections offering the `dmf` engine — mirrors the backend's
 *  `engines_for('snowflake')` (`backend/app/datasources/engines.py`); Freshness
 *  is the only type where BOTH engines apply, so this is what gates its picker. */
export function offersDmfEngine(connectionType: ConnectionType | undefined): boolean {
  return connectionType === 'snowflake';
}

const COLUMN: ConfigField = { name: 'column', label: 'Column', type: 'string' };

