// Re-derives dimension/engine/thresholds on a type switch, mirroring CheckNew's reset. Unlike
// CheckNew this form has no wholesale resetFields() (edit mode keeps everything else the author
// typed), so a stale value left in the antd store (which survives a field unmounting) would ride
// straight into buildCheckPayload — always resolve engine to a concrete value (never leave it
// undefined for a picker that may already be mounted to "re-default"), and clear the threshold
// fields when the new type doesn't accept them.
const initialType = check.expectation_type;
useEffect(() => {
  if (selectedType && selectedType !== initialType) {
    const nextSpec = EXPECTATION_BY_TYPE[selectedType];
    form.setFieldsValue({
      dimension: nextSpec?.dimension,
      engine: nextSpec?.engine ?? 'gx',
      ...(nextSpec?.noThresholds
        ? { warn_threshold: null, fail_threshold: null, critical_threshold: null }
        : {}),
    });
  }
}, [selectedType, initialType, form]);

